def split_horses(n, m, enemies):
    from collections import defaultdict

    # Build the graph
    graph = defaultdict(list)
    for a, b in enemies:
        graph[a].append(b)
        graph[b].append(a)

    # Try to color the graph using two colors (0 and 1)
    color = [-1] * (n + 1)

    def dfs(node, c):
        color[node] = c
        for neighbor in graph[node]:
            if color[neighbor] == -1:
                if not dfs(neighbor, 1 - c):
                    return False
            elif color[neighbor] == c:
                return False
        return True

    # Check if the graph is bipartite
    for i in range(1, n + 1):
        if color[i] == -1:
            if not dfs(i, 0):
                return "-1"

    # Convert the color array to the required output format
    return ''.join('0' if c == 0 else '1' for c in color[1:])

